def mean_and_median(numbers: list[float]) -> tuple[float, float]:
    if not numbers:
        raise ValueError("Cannot compute mean and median of an empty list")

    n = len(numbers)
    mean = sum(numbers) / n

    sorted_numbers = sorted(numbers)
    if n % 2 == 1:
        median = sorted_numbers[n // 2]
    else:
        mid1 = sorted_numbers[n // 2 - 1]
        mid2 = sorted_numbers[n // 2]
        median = (mid1 + mid2) / 2

    return (mean, median)
```

