def compute_mode(nums: list[int]) -> list[int]:
    if not nums:
        return []
    freq = {}
    for n in nums:
        freq[n] = freq.get(n, 0) + 1
    max_freq = max(freq.values())
    modes = [n for n, f in freq.items() if f == max_freq]
    modes.sort()
    return modes
