        return 0.0

    # Filter to positive numbers only
    positive_pairs = [(v, w) for v, w in zip(vals, weights) if v > 0]

    if not positive_pairs:
        return 0.0

    total_weight = sum(w for _, w in positive_pairs)
    if total_weight == 0:
        return 0.0

    # Weighted harmonic mean = sum(weights) / sum(weights / values)
    weighted_sum_inv = sum(w / v for v, w in positive_pairs)

    if weighted_sum_inv == 0:
        return 0.0

    result = total_weight / weighted_sum_inv
    return round(result, 3)
