def weighted_harmonic_mean(vals: list[float], weights: list[float]) -> float:
    if not vals or len(vals) != len(weights):
        return 0.0

    # Filter out non-positive values and their corresponding weights
    filtered_vals = []
    filtered_weights = []
    for v, w in zip(vals, weights):
        if v > 0:
            filtered_vals.append(v)
            filtered_weights.append(w)

    if not filtered_vals:
        return 0.0

    sum_weights = sum(filtered_weights)
    if sum_weights == 0:
        return 0.0

    # Weighted harmonic mean = sum(weights) / sum(weights / vals)
    sum_w_over_v = sum(w / v for w, v in zip(filtered_weights, filtered_vals))

    if sum_w_over_v == 0:
