def count_interval_overlaps(intervals: list[tuple[int, int]]) -> int:
    n = len(intervals)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            s1, e1 = intervals[i]
            s2, e2 = intervals[j]
            if s1 <= e2 and s2 <= e1:
                count += 1
    return count
