def count_subsequence_matches(text: str, sub: str) -> int:
    n = len(text)
    m = len(sub)
    if m == 0:
        return 1
    if n == 0:
        return 0

    # dp[i][j] = number of ways to form sub[j:] as a subsequence of text[i:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: empty sub can be formed in 1 way
    for i in range(n + 1):
        dp[i][m] = 1

    # Fill the table
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            # Option 1: skip text[i]
            dp[i][j] = dp[i + 1][j]
            # Option 2: use text[i] if it matches sub[j]
            if text[i] == sub[j]:
                dp[i][j] += dp[i + 1][j + 1]

    return dp[0][0]
