def count_subsequence_matches(text: str, sub: str) -> int:
    """
    Count the number of ways to form `sub` as a subsequence of `text`.
    Two selections are considered different if they use different indices in `text`.
    """
    n = len(text)
    m = len(sub)

    if m == 0:
        return 1
    if n == 0:
        return 0

    # dp[j] = number of ways to form sub[:j] as a subsequence of the processed prefix of text
    dp = [0] * (m + 1)
    dp[0] = 1  # empty subsequence can be formed in 1 way

    for i in range(n):
        # Traverse backwards to avoid using the same character multiple times in one step
        for j in range(m, 0, -1):
            if text[i] == sub[j - 1]:
                dp[j] += dp[j - 1]

    return dp[m]

def count_subsequence_matches(text: str, sub: str) -> int:
    """
    Count the number of ways to form `sub` as a subsequence of `text`.

    Args:
        text: The input string to search in.
        sub: The subsequence to find.

    Returns:
        The number of distinct ways to form `sub` as a subsequence of `text`.
    """
    if not sub:
        return 1
    if not text:
        return 0

    # dp[j] represents the number of ways to form sub[:j+1] as a subsequence
    # of the processed part of text
    dp = [0] * len(sub)
    dp[0] = 0

    for char in text:
        # Traverse sub in reverse to avoid using the same character multiple times
        for j in range(len(sub) - 1, -1, -1):
            if char == sub[j]:
                if j == 0:
                    dp[j] += 1
                else:
                    dp[j] += dp[j - 1]

    return dp[-1]

