def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)
    # dp[i][j] = length of LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    # Now reconstruct the lexicographically smallest LCS
    # We use memoization to avoid recomputation
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def solve(i, j):
        if i == n or j == m:
            return ""
        if a[i] == b[j]:
            return a[i] + solve(i + 1, j + 1)
        # We need to choose the lexicographically smallest result
        # Option 1: skip a[i], take LCS of a[i+1:] and b[j:]
        # Option 2: skip b[j], take LCS of a[i:] and b[j+1:]
        # But we need to be careful: we want the lexicographically smallest string
        # of maximum length.

        # First, check which options give the maximum length
        len1 = dp[i + 1][j]  # skip a[i]
        len2 = dp[i][j + 1]  # skip b[j]

        if len1 > len2:
            return solve(i + 1, j)
        elif len2 > len1:
            return solve(i, j + 1)
        else:
            # Both give same length, pick lexicographically smaller
            s1 = solve(i + 1, j)
            s2 = solve(i, j + 1)
            return min(s1, s2)

    return solve(0, 0)
