def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    if start == goal:
        return (0, [start])

    # Build adjacency list
    adj = {}
    for u, v, w in edges:
        if u not in adj:
            adj[u] = []
        if v not in adj:
            adj[v] = []
        adj[u].append((v, w))
        adj[v].append((u, w))

    # Dijkstra's algorithm with lexicographic tie-breaking
    # State: (cost, path) where path is list of nodes
    # We want to minimize cost first, then lexicographic order of path

    import heapq

    # Priority queue: (cost, path)
    # But we need to compare paths lexicographically when costs are equal
    # We'll use a custom comparison: (cost, path)

    # Initialize
    # dist[node] = (cost, path)
    dist = {}
    dist[start] = (0, [start])

    heap = [(0, [start])]

    while heap:
        cost, path = heapq.heappop(heap)
        current = path[-1]

        # Check if we've reached the goal
        if current == goal:
            return (cost, path)

        # Skip if we've already found a better path to this node
        if current in dist:
            if dist[current][0] < cost:
                continue
            if dist[current][0] == cost and dist[current][1] < path:
                continue

        # Explore neighbors
        if current not in adj:
            continue

        for neighbor, w in adj[current]:
            new_cost = cost + w
            new_path = path + [neighbor]

            if neighbor not in dist:
                dist[neighbor] = (new_cost, new_path)
                heapq.heappush(heap, (new_cost, new_path))
            else:
                old_cost, old_path = dist[neighbor]
                if new_cost < old_cost:
                    dist[neighbor] = (new_cost, new_path)
                    heapq.heappush(heap, (new_cost, new_path))
                elif new_cost == old_cost and new_path < old_path:
                    dist[neighbor] = (new_cost, new_path)
                    heapq.heappush(heap, (new_cost, new_path))

    return None
