def find_bridges(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if n == 0 or not edges:
        return []

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Tarjan's algorithm for finding bridges
    disc = [-1] * n
    low = [-1] * n
    parent = [-1] * n
    time = 0
    bridges = []

    def dfs(u):
        nonlocal time
        disc[u] = low[u] = time
        time += 1

        for v in adj[u]:
            if v == parent[u]:
                continue
            if disc[v] == -1:
                parent[v] = u
                dfs(v)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    a, b = min(u, v), max(u, v)
                    bridges.append((a, b))
            else:
                low[u] = min(low[u], disc[v])

    for i in range(n):
        if disc[i] == -1:
            dfs(i)

    bridges.sort()
    return bridges

