def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        results = []
        for op in operations:
            if op[0] == "get":
                results.append(None)
        return (results, [])

    # Use OrderedDict to maintain order of keys from least to most recently used
    from collections import OrderedDict

    cache = OrderedDict()
    results = []

    for op in operations:
        if op[0] == "put":
            _, key, value = op
            if key in cache:
                # Move to most recently used
                cache.move_to_end(key)
                cache[key] = value
            else:
                # Add as most recently used
                cache[key] = value
                if len(cache) > capacity:
                    # Remove least recently used
                    cache.popitem(last=False)
        elif op[0] == "get":
            _, key = op
            if key in cache:
                # Move to most recently used
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(None)

    keys = list(cache.keys())
    return (results, keys)
