from datetime import datetime, timedelta

def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    if n == 0:
        return start

    holiday_set = set(holidays)
    dt = datetime.strptime(start, "%Y-%m-%d")

    if n > 0:
        count = 0
        while count < n:
            dt += timedelta(days=1)
            date_str = dt.strftime("%Y-%m-%d")
            # Business day: Mon-Fri (weekday 0-4) and not a holiday
            if dt.weekday() < 5 and date_str not in holiday_set:
                count += 1
    else:
        count = 0
        while count > n:
            dt -= timedelta(days=1)
            date_str = dt.strftime("%Y-%m-%d")
