def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return abs(a)

    def lcm(a: int, b: int) -> int:
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // gcd(a, b)

    def extended_gcd(a: int, b: int) -> tuple[int, int, int]:
        if b == 0:
            return (a, 1, 0)
        g, x1, y1 = extended_gcd(b, a % b)
        return (g, y1, x1 - (a // b) * y1)

    # Start with the first congruence
    r, m = congruences[0]
    r = r % m
    x = r
    L = m

    for r, m in congruences[1:]:
        r = r % m
        g = gcd(L, m)
        # Check if the system is consistent
        if (r - x) % g != 0:
            return None

        # Solve: x + L * t ≡ r (mod m)
        # L * t ≡ (r - x) (mod m)
        # Divide by g: (L/g) * t ≡ (r - x)/g (mod m/g)
        L_g = L // g
        m_g = m // g
        rhs = (r - x) // g

        # Find inverse of L_g mod m_g
        # Since gcd(L_g, m_g) = 1, inverse exists
        inv, _, _ = extended_gcd(L_g, m_g)
        inv = inv % m_g

        t = (rhs * inv) % m_g

        # New solution: x_new = x + L * t
        x_new = x + L * t
        L_new = lcm(L, m)

        x = x_new % L_new
        L = L_new

    return (x, L)
