def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    num_cols = len(rows[0])

    # Calculate column widths
    col_widths = [0] * num_cols
    for row in rows:
        for i, cell in enumerate(row):
            col_widths[i] = max(col_widths[i], len(cell))

    # Format each cell
    def format_cell(cell: str, width: int, align: str) -> str:
        padding = width - len(cell)
        if align == 'l':
            return cell + ' ' * padding
        elif align == 'r':
            return ' ' * padding + cell
        elif align == 'c':
            left_pad = padding // 2
            right_pad = padding - left_pad
            return ' ' * left_pad + cell + ' ' * right_pad
        else:
            # Default to left
            return cell + ' ' * padding

    # Build the table
    lines = []
    for row in rows:
        formatted_cells = []
        for i, cell in enumerate(row):
            align = aligns[i] if i < len(aligns) else 'l'
            formatted_cells.append(format_cell(cell, col_widths[i], align))
        lines.append(' | '.join(formatted_cells))

    return '\n'.join(lines)
