        # current_m * k ≡ r - current_r (mod m)
        diff = r - current_r
        g = gcd(current_m, m)

        if diff % g != 0:
            return None

        # Reduce the equation
        cm = current_m // g
        mm = m // g
        d = diff // g

        # Solve cm * k ≡ d (mod mm)
        # Since gcd(cm, mm) = 1, find inverse of cm mod mm
        x, y, _ = extended_gcd(cm, mm)
        inv = x % mm
        k = (d * inv) % mm

        # New solution
        new_r = (current_r + current_m * k) % (current_m * mm)
        new_m = current_m * mm  # lcm(current_m, m)

        current_r = new_r
        current_m = new_m

