def format_table(rows: list[list[str]], aligns: str) -> str:
    """
    Format a table with given rows and alignment specifications.

    Args:
        rows: A list of lists of strings representing table rows.
        aligns: A string where each character specifies the alignment for the corresponding column.
                'l' for left, 'r' for right, 'c' for center.

    Returns:
        A formatted table as a string.
    """
    if not rows:
        return ""

    num_cols = len(rows[0])

    # Calculate the maximum width for each column
    col_widths = [0] * num_cols
    for row in rows:
        for i, cell in enumerate(row):
            if i < num_cols:
                col_widths[i] = max(col_widths[i], len(cell))

    # Build the formatted table
    lines = []
    for row in rows:
        formatted_cells = []
        for i, cell in enumerate(row):
            if i >= num_cols:
                break
            width = col_widths[i]
            align = aligns[i] if i < len(aligns) else 'l'
            if align == 'l':
                formatted_cells.append(cell.ljust(width))
            elif align == 'r':
                formatted_cells.append(cell.rjust(width))
            elif align == 'c':
                formatted_cells.append(cell.center(width))
            else:
                formatted_cells.append(cell.ljust(width))
        lines.append(" | ".join(formatted_cells))

    return "\n".join(lines)
