def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]

    for layer in range(n // 2):
        top, bottom = layer, n - 1 - layer
        left, right = layer, n - 1 - layer

        # Extract the ring elements in clockwise order starting from top-left
        ring = []
        # Top row: left to right
        for col in range(left, right + 1):
            ring.append(matrix[top][col])
        # Right column: top+1 to bottom
        for row in range(top + 1, bottom + 1):
            ring.append(matrix[row][right])
        # Bottom row: right-1 to left (if bottom > top)
        if bottom > top:
            for col in range(right - 1, left - 1, -1):
                ring.append(matrix[bottom][col])
        # Left column: bottom-1 to top+1 (if right > left)
        if right > left:
            for row in range(bottom - 1, top, -1):
                ring.append(matrix[row][left])

        ring_len = len(ring)
        if ring_len == 0:
            continue

        # Effective rotation
        shift = k % ring_len
        if shift < 0:
            shift += ring_len

        # Rotate: new_ring[i] = ring[(i - shift) % ring_len]
        # This means each element moves clockwise by shift positions
        new_ring = [0] * ring_len
        for i in range(ring_len):
            new_ring[i] = ring[(i - shift) % ring_len]

        # Place back into result
        idx = 0
        # Top row
        for col in range(left, right + 1):
            result[top][col] = new_ring[idx]
            idx += 1
        # Right column
        for row in range(top + 1, bottom + 1):
            result[row][right] = new_ring[idx]
            idx += 1
        # Bottom row
        if bottom > top:
            for col in range(right - 1, left - 1, -1):
                result[bottom][col] = new_ring[idx]
                idx += 1
        # Left column
        if right > left:
            for row in range(bottom - 1, top, -1):
                result[row][left] = new_ring[idx]
                idx += 1

    return result
