def expand_template(template: str, values: dict[str, str]) -> str:
    result = []
    i = 0
    n = len(template)
    while i < n:
        if template[i] == '{':
            if i + 1 < n and template[i + 1] == '{':
                result.append('{')
                i += 2
            else:
                # Find the nearest following '}'
                j = template.find('}', i + 1)
                if j == -1:
                    # No '}' after this '{', keep as ordinary character
                    result.append('{')
                    i += 1
                else:
                    key = template[i + 1:j]
                    if key in values:
                        result.append(values[key])
                        i = j + 1
                    else:
                        # Keep placeholder unchanged
                        result.append(template[i:j + 1])
                        i = j + 1
        elif template[i] == '}':
            if i + 1 < n and template[i + 1] == '}':
                result.append('}')
                i += 2
            else:
                result.append('}')
                i += 1
        else:
            result.append(template[i])
            i += 1
    return ''.join(result)
