def tidy_punctuation(text: str) -> str:
    import re

    # Step 1: Replace every run of whitespace with a single space, strip leading/trailing
    text = re.sub(r'\s+', ' ', text).strip()

    # Step 2: Remove space directly followed by one of , . ; : ! ?
    text = re.sub(r' ([,.;:!?\])', r'\1', text)

    # Step 3: After each of those six characters that is directly followed by a letter, insert a single space
    text = re.sub(r'([,.;:!?\])([a-zA-Z])', r'\1 \2', text)

    # Step 4: Capitalize first character and every character that comes right after one of . ! ? plus one space
    # We need to uppercase the first char, and any char after ". " "! " "? "
    result = []
    i = 0
    n = len(text)
    if n == 0:
        return ""

    # First character
    if text[0].isalpha():
        result.append(text[0].upper())
    else:
        result.append(text[0])
    i = 1

    while i < n:
        # Check if we're at a position that comes right after ". " "! " or "? "
        # That means text[i-2] is one of . ! ? and text[i-1] is space
        if i >= 2 and text[i-2] in '.!?' and text[i-1] == ' ':
            if text[i].isalpha():
                result.append(text[i].upper())
            else:
                result.append(text[i])
        else:
            result.append(text[i])
        i += 1

    return ''.join(result)

