def identifier_to_snake(name: str) -> str:
    if not name:
        return ""

    # Split by _ and -
    parts = []
    current = []
    for ch in name:
        if ch in ('_', '-'):
            if current:
                parts.append(''.join(current))
                current = []
        else:
            current.append(ch)
    if current:
        parts.append(''.join(current))

    # Now split each part by camelCase rules
    words = []
    for part in parts:
        if not part:
            continue
        # Split within part
        sub_words = []
        i = 0
        n = len(part)
        start = 0
        while i < n:
            if i > 0:
                prev = part[i - 1]
                curr = part[i]
                # Check for split points
                split_here = False
                # lowercase to uppercase
                if prev.islower() and curr.isupper():
                    split_here = True
                # letter to digit
                if prev.isalpha() and curr.isdigit():
                    split_here = True
                # digit to letter
                if prev.isdigit() and curr.isalpha():
                    split_here = True
                # two consecutive uppercase, and next is lowercase
                if prev.isupper() and curr.isupper() and i + 1 < n and part[i + 1].islower():
                    split_here = True

                if split_here:
                    sub_words.append(part[start:i])
                    start = i
            i += 1
        sub_words.append(part[start:])
        words.extend(sub_words)

    # Filter out empty words
    words = [w for w in words if w]

    if not words:
        return ""

    return '_'.join(w.lower() for w in words)
