def identifier_to_snake(name: str) -> str:
    """
    Convert an identifier to snake_case.

    Splits the identifier into words based on:
    - Underscores and hyphens as separators (discarded)
    - Transitions between lowercase and uppercase letters
    - Transitions between letters and digits
    - Consecutive uppercase letters where the second is followed by a lowercase letter

    Returns the words in lowercase, joined by single underscores.
    """
    if not name:
        return ""

    # First, split by underscores and hyphens, ignoring empty fragments
    fragments = []
    current = []
    for char in name:
        if char in ('_', '-'):
            if current:
                fragments.append(''.join(current))
                current = []
        else:
            current.append(char)
    if current:
        fragments.append(''.join(current))

    # If no fragments, return empty string
    if not fragments:
        return ""

    # Now split each fragment into words based on the rules
    words = []
    for fragment in fragments:
        if not fragment:
            continue

        # Split the fragment into words
        current_word = [fragment[0]]

        for i in range(1, len(fragment)):
            prev = fragment[i-1]
            curr = fragment[i]

            # Check if we need to split before curr
            split = False

            # Rule 1: Between lowercase and uppercase
            if prev.islower() and curr.isupper():
                split = True
            # Rule 2: Between letter and digit
            elif prev.isalpha() and curr.isdigit():
                split = True
            # Rule 3: Between digit and letter
            elif prev.isdigit() and curr.isalpha():
                split = True
            # Rule 4: Between two consecutive uppercase letters when the second is followed by a lowercase letter
            elif prev.isupper() and curr.isupper():
                # Check if curr is followed by a lowercase letter
                if i + 1 < len(fragment) and fragment[i+1].islower():
                    split = True

            if split:
                words.append(''.join(current_word))
                current_word = [curr]
            else:
                current_word.append(curr)

        if current_word:
            words.append(''.join(current_word))

    # If no words, return empty string
    if not words:
        return ""

    # Convert to lowercase and join with underscores
    return '_'.join(word.lower() for word in words)
