def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    # Check for items larger than capacity
    for s in sizes:
        if s > capacity:
            raise ValueError(f"Item size {s} exceeds bin capacity {capacity}")

    # Sort items in descending order
    sorted_sizes = sorted(sizes, reverse=True)

    bins = []  # List of bins, each bin is a list of item sizes
    bin_totals = []  # Current total of each bin

    for item in sorted_sizes:
        placed = False
        for i in range(len(bins)):
            if bin_totals[i] + item <= capacity:
                bins[i].append(item)
                bin_totals[i] += item
                placed = True
                break
        if not placed:
            bins.append([item])
            bin_totals.append(item)

    return bins
