def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    """
    Calculate league table from match results.

    Args:
        results: List of tuples (team1, team2, score1, score2)

    Returns:
        List of tuples (team, points, goals_for, goals_against)
        sorted by points (desc), then goal difference (desc), then goals for (desc), then name (asc)
    """
    teams = {}

    for team1, team2, score1, score2 in results:
        # Initialize teams if not present
        if team1 not in teams:
            teams[team1] = {'points': 0, 'goals_for': 0, 'goals_against': 0}
        if team2 not in teams:
            teams[team2] = {'points': 0, 'goals_for': 0, 'goals_against': 0}

        # Update stats
        teams[team1]['goals_for'] += score1
        teams[team1]['goals_against'] += score2
        teams[team2]['goals_for'] += score2
        teams[team2]['goals_against'] += score1

        # Update points
        if score1 > score2:
            teams[team1]['points'] += 3
        elif score2 > score1:
            teams[team2]['points'] += 3
        else:
            teams[team1]['points'] += 1
            teams[team2]['points'] += 1

    # Create list of tuples for sorting
    table = []
    for team, stats in teams.items():
        table.append((team, stats['points'], stats['goals_for'], stats['goals_against']))

    # Sort by points (desc), goal difference (desc), goals for (desc), name (asc)
    table.sort(key=lambda x: (-x[1], -(x[2] - x[3]), -x[2], x[0]))

    return table

