    # Track frozen accounts
    frozen = set()
    failed = []

    for idx, op in enumerate(ops):
        if not op:
            failed.append(idx)
            continue
        op_name = op[0]

        # Check if operation name is valid
        if op_name not in ('deposit', 'withdraw', 'transfer', 'freeze', 'unfreeze'):
            failed.append(idx)
            continue

        # Check account existence and amount validity based on operation type
        if op_name == 'deposit':
            if len(op) != 3:
                failed.append(idx)
                continue
            _, account, amount = op
            if account not in bal:
                failed.append(idx)
                continue
            if not isinstance(amount, int) or amount <= 0:
                failed.append(idx)
                continue
            if account in frozen:
                failed.append(idx)
                continue
            bal[account] += amount

        elif op_name == 'withdraw':
            if len(op) != 3:
                failed.append(idx)
                continue
            _, account, amount = op
            if account not in bal:
                failed.append(idx)
                continue
            if not isinstance(amount, int) or amount <= 0:
                failed.append(idx)
                continue
            if account in frozen:
                failed.append(idx)
                continue
            if bal[account] - amount < 0:
                failed.append(idx)
                continue
            bal[account] -= amount

        elif op_name == 'transfer':
            if len(op) != 4:
                failed.append(idx)
                continue
            _, source, target, amount = op
            if source not in bal or target not in bal:
                failed.append(idx)
                continue
            if not isinstance(amount, int) or amount <= 0:
                failed.append(idx)
                continue
            if source == target:
                failed.append(idx)
                continue
            if source in frozen or target in frozen:
                failed.append(idx)
                continue
            # Fee is 2, so total deduction from source is amount + 2
            if bal[source] - (amount + 2) < 0:
                failed.append(idx)
                continue
            bal[source] -= (amount + 2)
            bal[target] += amount

        elif op_name == 'freeze':
            if len(op) != 2:
                failed.append(idx)
                continue
            _, account = op
            if account not in bal:
                failed.append(idx)
                continue
            # Freezing an already frozen account succeeds but changes nothing
            if account not in frozen:
                frozen.add(account)

        elif op_name == 'unfreeze':
            if len(op) != 2:
                failed.append(idx)
                continue
            _, account = op
            if account not in bal:
                failed.append(idx)
                continue
            # Unfreezing an unfrozen account succeeds but changes nothing
            if account in frozen:
                frozen.remove(account)
        else:
            # Should not reach here due to earlier check
            failed.append(idx)

    return (bal, failed)
