def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock: dict[str, int] = {}
    waiting: list[tuple[str, int]] = []
    waiting_by_item: dict[str, list[int]] = {}
    has_waiting: dict[str, bool] = {}

    for kind, item, quantity in events:
        if item not in stock:
            stock[item] = 0
            waiting_by_item[item] = []
            has_waiting[item] = False

        if kind == 'receive':
            stock[item] += quantity
            # Process waiting orders for this item
            queue = waiting_by_item[item]
            while queue and stock[item] >= queue[0]:
                q = queue.pop(0)
                stock[item] -= q
                # Remove from global waiting list
                waiting.remove((item, q))
            has_waiting[item] = len(queue) > 0
        else:  # 'order'
            if not has_waiting[item] and stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting_by_item[item].append(quantity)
                waiting.append((item, quantity))
                has_waiting[item] = True

    return stock, waiting
