def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock: dict[str, int] = {}
    waiting_queues: dict[str, list[int]] = {}
    waiting_order: list[tuple[str, int]] = []  # (item, quantity) in order of placement

    for kind, item, quantity in events:
        if item not in stock:
            stock[item] = 0
            waiting_queues[item] = []

        if kind == 'receive':
            stock[item] += quantity
            # Ship waiting orders in order
            queue = waiting_queues[item]
            while queue:
                if stock[item] >= queue[0]:
                    # Ship the first waiting order
                    qty = queue.pop(0)
                    stock[item] -= qty
                    # Remove from waiting_order
                    waiting_order.remove((item, qty))
                else:
                    break
        elif kind == 'order':
            # Check if there's an earlier order still waiting for this item
            if waiting_queues[item]:
                # There's already a waiting order, so this one joins the queue
                waiting_queues[item].append(quantity)
                waiting_order.append((item, quantity))
            else:
                # No earlier waiting order, check if stock is sufficient
                if stock[item] >= quantity:
                    stock[item] -= quantity
                else:
                    # Join the waiting queue
                    waiting_queues[item].append(quantity)
                    waiting_order.append((item, quantity))

    return stock, waiting_order
