    stock: dict[str, int] = {}
    waiting: list[tuple[str, int]] = []
    # Per-item waiting queues to preserve order
    item_waiting: dict[str, list[int]] = {}

    def fulfill(item: str) -> None:
        """Fulfill waiting orders for item as much as stock allows."""
        if item not in item_waiting:
            return
        q = item_waiting[item]
        while q and stock.get(item, 0) >= q[0]:
            qty = q.pop(0)
            stock[item] -= qty
            # Remove from global waiting list
            waiting.remove((item, qty))
        # If q is empty, we can clean up
        if not q:
            del item_waiting[item]

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] = stock.get(item, 0) + quantity
            fulfill(item)
        elif kind == 'order':
            # Check if there's any pending order for this item
            has_pending = item in item_waiting and len(item_waiting[item]) > 0
            if not has_pending and stock.get(item, 0) >= quantity:
                # Fulfill immediately
                stock[item] -= quantity
            else:
                # Add to waiting queue
                waiting.append((item, quantity))
                if item not in item_waiting:
                    item_waiting[item] = []
                item_waiting[item].append(quantity)

    return stock, waiting

