                is_first = True
                for j in range(i):
                    if waiting[j][0] == item:
                        is_first = False
                        break
                if not is_first:
                    i += 1
                    continue
                # Check if stock covers this order
                if stock[item] >= w_qty:
                    stock[item] -= w_qty
                    waiting.pop(i)
                    # Don't increment i, check next at same position
                else:
                    # Can't fulfill this one, stop processing for this item
