def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Bases must be between 2 and 36")

    if number == "":
        raise ValueError("Empty string")

    negative = False
    if number[0] == '-':
        negative = True
        number = number[1:]

    if number == "":
        raise ValueError("Invalid number")

    # Validate and convert to integer
    value = 0
    for ch in number:
        c = ch.lower()
        if c.isdigit():
            d = int(c)
        elif c.isalpha():
            d = ord(c) - ord('a') + 10
        else:
