        if d >= from_base:
            raise ValueError(f"Digit {ch} not valid in base {from_base}")
        value = value * from_base + d

    if value == 0:
        return "0"

    # Convert to target base
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    result = []
    while value > 0:
