def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Bases must be between 2 and 36")

    if number == "" or number == "-":
        raise ValueError("Invalid number")

    negative = False
    if number[0] == '-':
        negative = True
        number = number[1:]
        if number == "":
            raise ValueError("Invalid number")

    # Validate and convert to decimal
    decimal_value = 0
    for ch in number:
        c = ch.lower()
        if c.isdigit():
            digit = int(c)
        elif c.isalpha():
            digit = ord(c) - ord('a') + 10
        else:
            raise ValueError(f"Invalid character {ch!r} in number")
        if digit >= from_base:
            raise ValueError(f"Digit {ch!r} is not valid in base {from_base}")
        decimal_value = decimal_value * from_base + digit

    if decimal_value == 0:
        return "0"

    # Convert decimal to target base
    digits = []
    n = decimal_value
    while n > 0:
        n, rem = divmod(n, to_base)
        if rem < 10:
            digits.append(str(rem))
        else:
            digits.append(chr(ord('a') + rem - 10))

    result = ''.join(reversed(digits))
    if negative:
        result = '-' + result
    return result
