def shortest_path_one_break(grid: list[str]) -> int:
    if not grid:
        return -1
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    # Find S and E
    start = None
    end = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # BFS with state (row, col, used_break)
    # used_break: 0 or 1
    from collections import deque

    # visited[r][c][b] where b is 0 or 1
    visited = [[[False, False] for _ in range(cols)] for _ in range(rows)]

    queue = deque()
    queue.append((start[0], start[1], 0, 0))  # row, col, used_break, distance
    visited[start[0]][start[1]][0] = True

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        r, c, used, dist = queue.popleft()

        if (r, c) == end:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                cell = grid[nr][nc]
                if cell == '#':
                    # Wall: can only enter if we haven't used a break yet
                    if used == 0 and not visited[nr][nc][1]:
                        visited[nr][nc][1] = True
                        queue.append((nr, nc, 1, dist + 1))
                else:
                    # Empty cell, S, or E
                    if not visited[nr][nc][used]:
                        visited[nr][nc][used] = True
                        queue.append((nr, nc, used, dist + 1))

    return -1
