        return -1

    rows = len(grid)
    cols = len(grid[0])

    start = end = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # BFS with state (row, col, used_break)
    # used_break: 0 or 1
    from collections import deque

    # dist[r][c][b] = minimum moves to reach (r,c) with b breaks used
    # Initialize with infinity
    INF = float('inf')
    dist = [[[INF, INF] for _ in range(cols)] for _ in range(rows)]

    dist[start[0]][start[1]][0] = 0
    dist[start[0]][start[1]][1] = INF  # Can't have used a break at start

    queue = deque()
    queue.append((start[0], start[1], 0))  # (row, col, breaks_used)

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
