    if not grid or not grid[0]:
        return -1

    rows = len(grid)
    cols = len(grid[0])

    # Find start and end
    start = None
    end = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # BFS with state (row, col, breaks_used)
    # breaks_used can be 0 or 1
    from collections import deque

    # visited[r][c][b] where b is 0 or 1
    visited = [[[False, False] for _ in range(cols)] for _ in range(rows)]

    queue = deque()
    queue.append((start[0], start[1], 0, 0))  # (row, col, breaks_used, steps)
    visited[start[0]][start[1]][0] = True

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        r, c, breaks, steps = queue.popleft()

        if (r, c) == end:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if nr < 0 or nr >= rows or nc < 0 or nc >= cols:
                continue

            cell = grid[nr][nc]

            if cell == '#':
                # Can break through if we haven't used a break yet
                if breaks == 0:
                    if not visited[nr][nc][1]:
                        visited[nr][nc][1] = True
                        queue.append((nr, nc, 1, steps + 1))
            else:
                # Empty cell, S, or E
                if not visited[nr][nc][breaks]:
                    visited[nr][nc][breaks] = True
                    queue.append((nr, nc, breaks, steps + 1))

    return -1

