def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    # Create a deep copy to avoid modifying the original grid
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    new_grid = [row[:] for row in grid]

    # Use a queue to track cells that need to be checked
    from collections import deque
    queue = deque()

    # Initialize queue with all cells that have >= 4 grains
    for r in range(rows):
        for c in range(cols):
            if new_grid[r][c] >= 4:
                queue.append((r, c))

    # Process until no more cells need to topple
    while queue:
        r, c = queue.popleft()
        if new_grid[r][c] >= 4:
            # Topple this cell
            new_grid[r][c] -= 4
            # Add 1 grain to each valid neighbor
            neighbors = [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]
            for nr, nc in neighbors:
                if 0 <= nr < rows and 0 <= nc < cols:
                    new_grid[nr][nc] += 1
                    if new_grid[nr][nc] >= 4:
                        queue.append((nr, nc))

    return new_grid
