from pathlib import Path


def read_user_file(base_dir: str, filename: str) -> bytes | None:
    """
    Read a file from base_dir/filename and return its content as bytes.
    Returns None if the file does not exist.
    """
    base_path = Path(base_dir)
    file_path = base_path / filename

    # Ensure the resolved path is within base_dir to prevent directory traversal
    try:
        resolved_base = base_path.resolve()
        resolved_file = file_path.resolve()
        # Check if resolved_file is within resolved_base
        if not str(resolved_file).startswith(str(resolved_base)):
            return None
    except (OSError, ValueError):
        return None

    if not resolved_file.is_file():
        return None

    try:
        with open(resolved_file, 'rb') as f:
            return f.read()
    except (OSError, IOError):
        return None

