import os
import posixpath

def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    # Normalize the request path to prevent directory traversal
    # Ensure it starts with /
    if not request_path.startswith('/'):
        return (404, b"Not Found")

    # Normalize the path to resolve any .. or . components
    # Use posixpath for consistent behavior
    normalized_path = posixpath.normpath(request_path)

    # If the path is just '/', serve index.html
    if normalized_path == '/':
        file_path = os.path.join(web_root, 'index.html')
    else:
        # Remove leading slash for joining
        relative_path = normalized_path.lstrip('/')
        file_path = os.path.join(web_root, relative_path)

    # Resolve the real path to prevent symlink attacks
    try:
        real_web_root = os.path.realpath(web_root)
        real_file_path = os.path.realpath(file_path)
    except (OSError, ValueError):
        return (404, b"Not Found")

    # Ensure the resolved file path is within the web root
    # Use commonpath to check if real_file_path is under real_web_root
    try:
        common = os.path.commonpath([real_web_root, real_file_path])
    except ValueError:
        # Different drives on Windows, or other issues
        return (404, b"Not Found")

    if common != real_web_root:
        return (404, b"Not Found")

    # Check if it's a regular file
    if not os.path.isfile(real_file_path):
        return (404, b"Not Found")

    # Read the file
    try:
        with open(real_file_path, 'rb') as f:
            body = f.read()
    except (OSError, IOError):
        return (404, b"Not Found")

    return (200, body)
