import posixpath


def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    """
    Serve a static file from web_root based on request_path.

    Args:
        web_root: The root directory for static files.
        request_path: The URL path (starts with '/', already URL-decoded).

    Returns:
        A tuple (status, body) where status is 200 if file found, 404 otherwise.
    """
    # Normalize the request path
    if not request_path.startswith('/'):
        return (404, b"Not Found")

    # If path is just '/', use index.html
    if request_path == '/':
        relative_path = 'index.html'
    else:
        # Remove leading slash and normalize
        relative_path = request_path.lstrip('/')
        # Normalize to prevent directory traversal
        relative_path = posixpath.normpath(relative_path)

    # Ensure the normalized path doesn't start with '..' or contain '..'
    if relative_path.startswith('..') or '/../' in relative_path or relative_path == '..':
        return (404, b"Not Found")

    # Build the full path
    full_path = os.path.join(web_root, relative_path)

    # Resolve the real path to prevent symlink attacks
    real_web_root = os.path.realpath(web_root)
    real_full_path = os.path.realpath(full_path)

    # Ensure the resolved path is within the web root
    if not real_full_path.startswith(real_web_root + os.sep) and real_full_path != real_web_root:
        return (404, b"Not Found")

    # Check if it's a regular file
    if not os.path.isfile(real_full_path):
        return (404, b"Not Found")

    # Read the file
    try:
        with open(real_full_path, 'rb') as f:
            body = f.read()
        return (200, body)
    except (IOError, OSError):
        return (404, b"Not Found")

import zipfile
import os

def extract_zip(zip_path: str, dest_dir: str) -> None:
    with zipfile.ZipFile(zip_path, 'r') as zip_ref:
        for member in zip_ref.namelist():
            target_path = os.path.join(dest_dir, member)
            # Create directories if needed
            if member.endswith('/'):
                os.makedirs(target_path, exist_ok=True)
            else:
                os.makedirs(os.path.dirname(target_path), exist_ok=True)
                # Extract the file
                zip_ref.extract(member, dest_dir)

