import yaml


def parse_config(text: str) -> dict:
    """
    Parse a YAML configuration string and return it as a dictionary.

    Args:
        text: A YAML string representing the configuration document.

    Returns:
        A dictionary representing the parsed configuration.
        Returns an empty dictionary if the document is empty.
    """
    if not text or not text.strip():
        return {}

    result = yaml.safe_load(text)

    if result is None:
        return {}

    if not isinstance(result, dict):
        raise ValueError("Top-level YAML node must be a mapping")

    return result
