def parse_config(text: str) -> dict:
    """
    Parse a configuration text into a dictionary.

    The configuration format is:
    - Lines with key=value pairs
    - Lines starting with # are comments
    - Empty lines are ignored
    - Values can be strings, numbers, booleans, or lists
    - Lists are specified as [item1, item2, item3]
    - Booleans are True/False (case-insensitive)
    - Numbers are integers or floats
    - Strings are everything else (stripped of whitespace)
    """
    config = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            continue
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        # Parse the value
        if value.startswith('[') and value.endswith(']'):
            # Parse list
            inner = value[1:-1].strip()
            if not inner:
                config[key] = []
            else:
                items = []
                # Split by comma, but handle quoted strings
                current = ''
                in_quotes = False
                quote_char = None
                for char in inner:
                    if char in ('"', "'") and not in_quotes:
                        in_quotes = True
                        quote_char = char
                        current += char
                    elif char == quote_char and in_quotes:
                        in_quotes = False
                        current += char
                    elif char == ',' and not in_quotes:
                        items.append(current.strip())
                        current = ''
                    else:
                        current += char
                if current.strip():
                    items.append(current.strip())

                # Parse each item
                parsed_items = []
                for item in items:
                    item = item.strip()
                    if item.startswith('"') and item.endswith('"'):
                        parsed_items.append(item[1:-1])
                    elif item.startswith("'") and item.endswith("'"):
                        parsed_items.append(item[1:-1])
                    elif item.lower() == 'true':
                        parsed_items.append(True)
                    elif item.lower() == 'false':
                        parsed_items.append(False)
                    else:
                        try:
                            parsed_items.append(int(item))
                        except ValueError:
                            try:
                                parsed_items.append(float(item))
                            except ValueError:
                                parsed_items.append(item)
                config[key] = parsed_items
        elif value.lower() == 'true':
            config[key] = True
        elif value.lower() == 'false':
            config[key] = False
        else:
            try:
                config[key] = int(value)
            except ValueError:
                try:
                    config[key] = float(value)
                except ValueError:
                    # Strip quotes if present
                    if (value.startswith('"') and value.endswith('"')) or (value.startswith("'") and value.endswith("'")):
                        config[key] = value[1:-1]
                    else:
                        config[key] = value

    return config
