def restore_cache_entry(blob: bytes) -> dict:
    """
    Restore a cache entry from a compressed and pickled byte blob.

    The blob is expected to be created via zlib.compress(pickle.dumps(entry)).
    This function safely decompresses and unpickles the data, ensuring that
    the result is a dictionary with valid types.

    Args:
        blob: The compressed and pickled byte data.

    Returns:
        The restored dictionary entry.

    Raises:
        ValueError: If the blob is not valid compressed/pickled data or doesn't contain a dict.
    """
    if not isinstance(blob, bytes):
        raise ValueError("Input must be bytes")

    if len(blob) == 0:
        raise ValueError("Empty blob")

    # Decompress the data
    try:
        decompressed = zlib.decompress(blob)
    except zlib.error as e:
        raise ValueError(f"Failed to decompress data: {e}")

    # Unpickle the data safely
    # We use a restricted unpickler to prevent arbitrary code execution
    class SafeUnpickler(pickle.Unpickler):
        def find_class(self, module, name):
            # Only allow basic types that are safe
            allowed = {
                ('builtins', 'dict'),
                ('builtins', 'list'),
                ('builtins', 'str'),
                ('builtins', 'int'),
                ('builtins', 'float'),
                ('builtins', 'bool'),
                ('builtins', 'NoneType'),
                ('builtins', 'tuple'),
            }
            if (module, name) not in allowed:
                raise pickle.UnpicklingError(f"Global '{module}.{name}' is forbidden")
            return super().find_class(module, name)

    try:
        entry = SafeUnpickler(io.BytesIO(decompressed)).load()
    except (pickle.UnpicklingError, EOFError, Exception) as e:
        raise ValueError(f"Failed to unpickle data: {e}")

    # Verify the result is a dictionary
    if not isinstance(entry, dict):
        raise ValueError("Restored entry is not a dictionary")

    # Validate the structure recursively
    def validate_value(value, depth=0):
        if depth > 100:  # Prevent excessive recursion
            raise ValueError("Maximum recursion depth exceeded")

        if isinstance(value, (str, int, float, bool, type(None))):
            return
        elif isinstance(value, list):
            for item in value:
                validate_value(item, depth + 1)
        elif isinstance(value, dict):
            for k, v in value.items():
                if not isinstance(k, str):
                    raise ValueError("Dictionary keys must be strings")
                validate_value(v, depth + 1)
        else:
            raise ValueError(f"Invalid value type: {type(value)}")

    for key, value in entry.items():
        if not isinstance(key, str):
            raise ValueError("Dictionary keys must be strings")
        validate_value(value)

    return entry
