import ast
import operator

def evaluate_expression(expression: str) -> float:
    """
    Safely evaluate an arithmetic expression string.

    Supports: decimal numbers, +, -, *, /, **, unary minus, parentheses, spaces.
    Raises ValueError for invalid expressions, ZeroDivisionError for division by zero.
    """
    if not expression or not expression.strip():
        raise ValueError("Empty expression")

    # Remove all whitespace for parsing
    expr = expression.replace(' ', '')

    # Validate characters
    allowed_chars = set('0123456789.+-*/()')
    for ch in expr:
        if ch not in allowed_chars:
            raise ValueError(f"Invalid character: {ch}")

    # Parse using ast
    try:
        tree = ast.parse(expr, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid expression syntax")

    # Define allowed operations
    allowed_ops = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos,
    }

    def _eval(node):
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        elif isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float)):
                return float(node.value)
            else:
                raise ValueError(f"Unsupported constant type: {type(node.value)}")
        elif isinstance(node, ast.Num):  # Python 3.7 and earlier
            return float(node.n)
        elif isinstance(node, ast.BinOp):
            if type(node.op) not in allowed_ops:
                raise ValueError(f"Unsupported operator: {type(node.op).__name__}")
            left = _eval(node.left)
            right = _eval(node.right)
            op_func = allowed_ops[type(node.op)]
            return op_func(left, right)
        elif isinstance(node, ast.UnaryOp):
            if type(node.op) not in allowed_ops:
                raise ValueError(f"Unsupported unary operator: {type(node.op).__name__}")
            operand = _eval(node.operand)
            op_func = allowed_ops[type(node.op)]
            return op_func(operand)
        else:
            raise ValueError(f"Unsupported expression element: {type(node).__name__}")

    try:
        result = _eval(tree)
        return float(result)
    except ZeroDivisionError:
        raise
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {e}")
