def matches_filter(expression: str, record: dict) -> bool:
    """
    Evaluate a filter expression against a record dictionary.

    Args:
        expression: A string containing a filter expression
        record: A dictionary of key-value pairs to use as variables

    Returns:
        True if the expression evaluates to True, False otherwise

    Raises:
        ValueError: If the expression is invalid or uses undefined names
    """
    # Define allowed names: only keys from record
    allowed_names = set(record.keys())

    # Define allowed builtins (empty - no builtins allowed)
    allowed_builtins = {}

    # Compile the expression
    try:
        code = compile(expression, '<filter>', 'eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid expression: {e}")

    # Check for any names used in the expression
    import ast
    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid expression: {e}")

    # Collect all names used in the expression
    class NameCollector(ast.NodeVisitor):
        def __init__(self):
            self.names = set()

        def visit_Name(self, node):
            self.names.add(node.id)
            self.generic_visit(node)

        def visit_Attribute(self, node):
            # Don't allow attribute access
            raise ValueError("Attribute access is not allowed")

        def visit_Call(self, node):
            # Don't allow function calls
            raise ValueError("Function calls are not allowed")

        def visit_Subscript(self, node):
            # Don't allow subscript access
            raise ValueError("Subscript access is not allowed")

    collector = NameCollector()
    collector.visit(tree)

    # Check that all names are in allowed_names
    for name in collector.names:
        if name not in allowed_names:
            raise ValueError(f"Undefined name: {name}")

    # Create the evaluation namespace
    namespace = dict(record)

    # Evaluate the expression
    try:
        result = eval(code, {"__builtins__": allowed_builtins}, namespace)
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {e}")

    return bool(result)
