def matches_filter(expression: str, record: dict) -> bool:
    """
    Evaluate a filter expression against a record dictionary.

    The expression can use keys of record as variable names, and contains
    comparison operators, boolean operators, and parentheses with Python precedence.

    Raises ValueError if the expression is invalid or uses unknown names.
    """
    import ast
    import operator

    # Define allowed operators
    allowed_binary_ops = {
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
    }

    allowed_unary_ops = {
        ast.Not: operator.not_,
        ast.USub: operator.neg,
    }

    allowed_bool_ops = {
        ast.And: lambda a, b: a and b,
        ast.Or: lambda a, b: a or b,
    }

    def evaluate(node, record):
        """Recursively evaluate an AST node."""
        if isinstance(node, ast.Expression):
            return evaluate(node.body, record)
        elif isinstance(node, ast.BoolOp):
            op_type = type(node.op)
            if op_type not in allowed_bool_ops:
                raise ValueError(f"Unsupported boolean operator: {op_type.__name__}")
            # Evaluate all values
            values = [evaluate(v, record) for v in node.values]
            if op_type == ast.And:
                return all(values)
            else:  # Or
                return any(values)
        elif isinstance(node, ast.UnaryOp):
            op_type = type(node.op)
            if op_type not in allowed_unary_ops:
                raise ValueError(f"Unsupported unary operator: {op_type.__name__}")
            operand = evaluate(node.operand, record)
            return allowed_unary_ops[op_type](operand)
        elif isinstance(node, ast.BinOp):
            op_type = type(node.op)
            if op_type not in allowed_binary_ops:
                raise ValueError(f"Unsupported binary operator: {op_type.__name__}")
            left = evaluate(node.left, record)
            right = evaluate(node.right, record)
            return allowed_binary_ops[op_type](left, right)
        elif isinstance(node, ast.Name):
            if node.id not in record:
                raise ValueError(f"Unknown name in expression: {node.id}")
            return record[node.id]
        elif isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Num):  # Python 3.7 and earlier
            return node.n
        elif isinstance(node, ast.Str):  # Python 3.7 and earlier
            return node.s
        elif isinstance(node, ast.NameConstant):  # Python 3.7 and earlier
            return node.value
        else:
            raise ValueError(f"Unsupported expression element: {type(node).__name__}")

    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid expression syntax: {e}")

    return evaluate(tree, record)
