            if node.keywords:
                raise ValueError("Keyword arguments not allowed")

    # Now evaluate safely
    # Create a safe namespace
    safe_globals = {
        'x': x,
        'sqrt': math.sqrt,
        'abs': abs,
        'sin': math.sin,
        'cos': math.cos,
        '__builtins__': {}
