def is_valid_email(s: str) -> bool:
    if s.count('@') != 1:
        return False

    local, domain = s.split('@')

    # Validate local part
    if not local:
        return False

    # Local must start and end with letter or digit
    if not (local[0].isalnum() and local[0].isascii()):
        return False
    if not (local[-1].isalnum() and local[-1].isascii()):
        return False

    # Check each character in local
    separators = set('._-')
    prev_was_separator = False
    for ch in local:
        if ch in separators:
            if prev_was_separator:
                return False
            prev_was_separator = True
        elif ch.isalnum() and ch.isascii():
            prev_was_separator = False
        else:
            return False

    # Validate domain part
    if not domain:
        return False

    labels = domain.split('.')
    if len(labels) < 2:
        return False

    for i, label in enumerate(labels):
        if not label:
            return False
        if i == len(labels) - 1:
            # Last label: at least two ASCII letters, nothing else
            if len(label) < 2:
                return False
            for ch in label:
                if not (ch.isalpha() and ch.isascii()):
                    return False
        else:
            # Non-last label: non-empty sequence of ASCII letters and digits
            for ch in label:
                if not (ch.isalnum() and ch.isascii()):
                    return False

    return True
