def is_valid_email(s: str) -> bool:
    if s.count('@') != 1:
        return False

    local, domain = s.split('@')

    # Validate local part
    if not local:
        return False

    # Local must start and end with letter or digit
    if not (local[0].isalnum() and local[0].isascii()):
        return False
    if not (local[-1].isalnum() and local[-1].isascii()):
        return False

    # Check each character in local
    separators = set('._-')
    prev_was_separator = False
    for ch in local:
        if ch in separators:
            if prev_was_separator:
                return False
            prev_was_separator = True
        elif ch.isalnum() and ch.isascii():
            prev_was_separator = False
        else:
            return False

    # Validate domain part
    if not domain:
        return False

    labels = domain.split('.')

    # Must have at least two labels
    if len(labels) < 2:
        return False

    # Check for empty labels (consecutive dots or leading/trailing dots)
    for label in labels:
        if not label:
            return False

    # Each label is non-empty sequence of ASCII letters and digits
    for label in labels:
        for ch in label:
            if not (ch.isalnum() and ch.isascii()):
                return False

    # Last label must consist of at least two ASCII letters and nothing else
    last_label = labels[-1]
    if len(last_label) < 2:
        return False
    for ch in last_label:
        if not (ch.isalpha() and ch.isascii()):
            return False

    return True
