    if s.count('@') != 1:
        return False

    local, domain = s.split('@')

    # Validate local part
    if not local:
        return False

    # Local must start and end with letter or digit
    if not (local[0].isalnum() and local[-1].isalnum()):
        return False

    # Check each character in local
    allowed_local_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-')
    for ch in local:
        if ch not in allowed_local_chars:
            return False

    # No two separator characters next to each other
    separators = set('._-')
    for i in range(len(local) - 1):
        if local[i] in separators and local[i+1] in separators:
            return False

    # Validate domain part
    if not domain:
        return False

    labels = domain.split('.')

    # At least two labels
    if len(labels) < 2:
        return False

    # Each label must be non-empty
    for label in labels:
        if not label:
            return False

    # Each label consists of ASCII letters and digits only
    for label in labels:
        for ch in label:
            if not (ch.isalnum() and ch.isascii()):
                return False

    # Last label must consist of at least two ASCII letters and nothing else
    last_label = labels[-1]
    if len(last_label) < 2:
        return False
    for ch in last_label:
        if not (ch.isalpha() and ch.isascii()):
            return False

    return True
