            if i > 0 and local[i-1] in '._-':
                return False
            if i < len(local) - 1 and local[i+1] in '._-':
                return False
        else:
            return False

    # Validate domain part
    if not domain:
        return False
    labels = domain.split('.')
    if len(labels) < 2:
