    """
    Encrypt plaintext using a simple XOR-based stream cipher with a repeating key.
    """
    if not key:
        raise ValueError("Key must not be empty")
    result = bytearray()
    for i, byte in enumerate(plaintext):
        result.append(byte ^ key[i % len(key)])
