import hashlib
import hmac


def hash_pin(pin: str) -> str:
    """
    Hash a numeric PIN (4-6 digits) using SHA-256 with a fixed salt.
    Returns the hex digest of the hash.
    Raises ValueError if pin is not a valid 4-6 digit numeric string.
    """
    if not isinstance(pin, str):
        raise ValueError("PIN must be a string")
    if not (4 <= len(pin) <= 6):
        raise ValueError("PIN must be 4 to 6 digits long")
    if not pin.isdigit():
        raise ValueError("PIN must contain only digits")

    # Use a fixed salt for deterministic hashing (for demonstration purposes)
    # In production, use a random salt stored alongside the hash
    salt = b"fixed_salt_for_pin_hashing"
    data = salt + pin.encode('utf-8')
    hash_obj = hashlib.sha256(data)
    return hash_obj.hexdigest()


def check_pin(pin: str, stored: str) -> bool:
    """
    Check if the given pin matches the stored hash.
    Returns True if pin is valid and its hash matches stored, False otherwise.
    """
    if not isinstance(pin, str) or not isinstance(stored, str):
        return False
    if not (4 <= len(pin) <= 6):
        return False
    if not pin.isdigit():
        return False

    try:
        computed_hash = hash_pin(pin)
    except ValueError:
        return False

    # Use constant-time comparison to prevent timing attacks
    return hmac.compare_digest(computed_hash, stored)
