def is_local_redirect(target: str, host: str) -> bool:
    # Check for backslash, space, or control characters
    for ch in target:
        if ch == '\\' or ch == ' ' or ord(ch) < 32 or ord(ch) == 127:
            return False

    # Case 1: site-relative path
    if target.startswith('/'):
        # The character after the first /, if there is one, must not be /
        if len(target) == 1:
            return True
        if target[1] != '/':
            return True
        else:
            return False

    # Case 2: absolute URL with http:// or https://
    lower_target = target.lower()
    if lower_target.startswith('http://') or lower_target.startswith('https://'):
        # Extract the host part
        # Remove the scheme
        if lower_target.startswith('http://'):
            rest = target[7:]
        else:
            rest = target[8:]

        # Find the end of the host part
        # Host ends at the first /, ?, or #
        end = len(rest)
        for i, ch in enumerate(rest):
            if ch in ('/', '?', '#'):
                end = i
                break

        host_part = rest[:end]

        # Remove user-info (before @)
        if '@' in host_part:
            host_part = host_part.split('@', 1)[1]

        # Remove port (after :)
        if ':' in host_part:
            host_part = host_part.split(':', 1)[0]

        # Compare case-insensitively
        return host_part.lower() == host.lower()

    return False
