def is_local_redirect(target: str, host: str) -> bool:
    """
    Check if a redirect target is a local redirect to the given host.

    Returns True if:
    1. target is a site-relative path (starts with exactly one '/', not followed by another '/')
    2. target is an absolute URL (http:// or https://) with the same host as the given host

    Returns False in all other cases, especially if target contains backslash, space,
    or control characters (code point < 32 or >= 127).
    """
    # Check for dangerous characters: backslash, space, or control characters
    for ch in target:
        code = ord(ch)
        if ch == '\\' or ch == ' ' or code < 32 or code >= 127:
            return False

    # Case 1: Site-relative path
    # Must start with exactly one '/', and the next character (if any) must not be '/'
    if target.startswith('/'):
        if len(target) == 1:
            # Just "/" is a valid site-relative path
            return True
        if target[1] == '/':
            # Starts with "//" - this is a protocol-relative URL, not a site-relative path
            return False
        return True

    # Case 2: Absolute URL with http:// or https://
    lower_target = target.lower()
    if lower_target.startswith('http://') or lower_target.startswith('https://'):
        # Parse the URL to extract the host
        # We need to handle the URL carefully to avoid security issues
        # Find the end of the scheme
        if lower_target.startswith('http://'):
            rest = target[7:]  # after "http://"
        else:
            rest = target[8:]  # after "https://"

