        # But we need to handle user-info and port
        # Find the end of the authority part
        end = len(rest)
        for i, ch in enumerate(rest):
            if ch in ('/', '?', '#'):
                end = i
                break

        authority = rest[:end]

        # Handle user-info: if there's an '@', the host is after the last '@'
        if '@' in authority:
            authority = authority.rsplit('@', 1)[1]

        # Handle port: if there's a ':', the host is before the first ':'
        # But we need to be careful with IPv6 addresses
        if ':' in authority:
            # Check if it's an IPv6 address (starts with '[')
            if authority.startswith('['):
