import ipaddress
import re


def is_public_ip(ip_str: str) -> bool:
    """
    Devuelve True si ip_str es una dirección IP en forma de texto estándar
    (IPv4 o IPv6) y esa dirección es enrutable públicamente.
    Devuelve False en caso contrario. Nunca lanza una excepción.
    """
    if not isinstance(ip_str, str):
        return False

    # Eliminar espacios en blanco alrededor (la especificación dice "sin espacios en blanco alrededor",
    # pero para ser robusto, comprobamos que no haya espacios en absoluto en la cadena)
    if ' ' in ip_str or '\t' in ip_str or '\n' in ip_str or '\r' in ip_str:
        return False

    # Comprobar que no hay corchetes, prefijos de longitud, sufijos de zona
    if '[' in ip_str or ']' in ip_str or '%' in ip_str:
        return False

    # Intentar parsear como IPv4
    try:
        # Verificar formato IPv4 estricto: cuatro números decimales 0-255, sin ceros a la izquierda
        # La función ipaddress.IPv4Address ya valida el formato, pero necesitamos asegurarnos
        # de que no tenga ceros a la izquierda
        parts = ip_str.split('.')
        if len(parts) == 4:
            for part in parts:
                if not part.isdigit():
                    return False
                if len(part) > 1 and part[0] == '0':
                    return False
                if int(part) > 255:
                    return False
            # Si llegamos aquí, el formato es válido
            try:
                ipv4 = ipaddress.IPv4Address(ip_str)
            except (ipaddress.AddressValueError, ValueError):
                return False

            # Verificar si es pública
            if ipv4.is_private:
                return False
            if ipv4.is_loopback:
                return False
            if ipv4.is_link_local:
                return False
            if ipv4.is_multicast:
                return False
            if ipv4.is_unspecified:
                return False
            if ipv4.is_reserved:
                return False
            if ipv4.is_documentation:
                return False
            # Verificar espacio de direcciones compartidas 100.64.0.0/10
            if ipaddress.IPv4Network('100.64.0.0/10').contains(ipv4):
                return False
            # Verificar dirección de difusión
            if ipv4 == ipaddress.IPv4Address('255.255.255.255'):
                return False

            return True
        else:
            # No es formato IPv4 válido
            return False
    except Exception:
        pass

    # Intentar parsear como IPv6
    try:
        # Verificar que no sea IPv4 mapeado a IPv6 (lo manejamos aparte)
        # Primero, comprobamos si es una dirección IPv6 válida
        ipv6 = ipaddress.IPv6Address(ip_str)

        # Verificar si es una dirección mapeada a IPv4 (::ffff:a.b.c.d)
        if ipv6.ipv4_mapped is not None:
            # Juzgar por la dirección IPv4 que contiene
            ipv4_mapped = ipv6.ipv4_mapped
            if ipv4_mapped.is_private:
                return False

