import os
import stat


def create_upload_dir(path: str) -> None:
    """
    Create the directory `path` (and any missing parent directories) for storing
    user-uploaded documents. The directory is owned by the current user and
    has permissions restricted to the owner only (0o700).

    If `path` already exists as a directory, return without error.
    If `path` exists but is not a directory, raise an error.
    """
    # Resolve the path to an absolute path to avoid ambiguity
    abs_path = os.path.abspath(path)

    # Check if the path already exists
    if os.path.exists(abs_path):
        if os.path.isdir(abs_path):
            # Already a directory, ensure permissions are secure
            try:
                os.chmod(abs_path, stat.S_IRWXU)  # 0o700
            except OSError:
                pass
            return
        else:
            # Path exists but is not a directory
            raise FileExistsError(f"Path exists and is not a directory: {abs_path}")

    # Create the directory with parent directories
    try:
        os.makedirs(abs_path, mode=stat.S_IRWXU, exist_ok=True)
    except FileExistsError:
        # Race condition: another process created it between our check and creation
        if os.path.isdir(abs_path):
            try:
                os.chmod(abs_path, stat.S_IRWXU)
            except OSError:
                pass
            return
        else:
            raise

    # Ensure permissions are set correctly (makedirs mode may be affected by umask)
    try:
        os.chmod(abs_path, stat.S_IRWXU)  # 0o700
    except OSError:
        pass
