def render_notification(template: str, variables: dict) -> str:
    from jinja2 import Environment, BaseLoader, StrictUndefined

    # Create a custom undefined class that returns empty string for missing variables
    class EmptyUndefined:
        def __init__(self, name):
            self.name = name

        def __str__(self):
            return ""

        def __iter__(self):
            return iter([])

        def __bool__(self):
            return False

        def __getattr__(self, name):
            if name.startswith('_'):
                raise AttributeError(name)
            return EmptyUndefined(name)

        def __getitem__(self, key):
            return EmptyUndefined(key)

        def __call__(self, *args, **kwargs):
            return EmptyUndefined("call")

    env = Environment(
        loader=BaseLoader(),
        undefined=EmptyUndefined,
        autoescape=False
    )

    # Convert all values to strings
    str_variables = {k: str(v) for k, v in variables.items()}

    try:
        tmpl = env.from_string(template)
        return tmpl.render(**str_variables)
    except Exception:
        # Fallback: manual parsing if jinja2 fails
        import re
        result = []
        last_end = 0
        pattern = re.compile(r'\{\{\s*(\w+)\s*\}\}')
        for match in pattern.finditer(template):
            result.append(template[last_end:match.start()])
            var_name = match.group(1)
            if var_name in str_variables:
                result.append(str_variables[var_name])
            else:
                result.append("")
            last_end = match.end()
        result.append(template[last_end:])
        return "".join(result)
