    - Missing variables are replaced with empty string
    - Values are inserted as-is (no escaping)
    - Secure against common vulnerabilities (sandboxed, no autoescape)
    """
    # Create a sandboxed environment for security
    env = SandboxedEnvironment(
        loader=BaseLoader(),
        undefined=StrictUndefined,
        autoescape=False,
        trim_blocks=True,
        lstrip_blocks=True,
    )

