            pass

        def __str__(self):
            return ""

        def __iter__(self):
            return iter([])

        def __bool__(self):
            return False

        def __getattr__(self, name):
            return EmptyUndefined()

        def __getitem__(self, key):
            return EmptyUndefined()

        def __call__(self, *args, **kwargs):
            return EmptyUndefined()

    env2 = SandboxedEnvironment(
        loader=BaseLoader(),
        undefined=EmptyUndefined,
        autoescape=False,
        trim_blocks=True,
        lstrip_blocks=True,
    )

    # Convert all variable values to strings
    string_vars = {k: str(v) for k, v in variables.items()}

