import jinja2
from jinja2 import Environment, BaseLoader


def render_report_header(template: str, report: dict) -> str:
    """
    Render a Jinja2 template with the given report dictionary.

    The template accesses report entries through the single variable `report`.
    Missing keys are replaced by empty strings.
    Values are converted to str and inserted without escaping.
    Conditional blocks like {% if report.draft %}...{% endif %} are supported.
    """
    # Create a custom environment with autoescape disabled
    env = Environment(
        loader=BaseLoader(),
        autoescape=False,
        undefined=jinja2.ChainableUndefined
    )

    # Create a wrapper class that returns empty string for missing keys
    class ReportWrapper:
        def __init__(self, data):
            self._data = data

        def __getattr__(self, name):
            if name.startswith('_'):
                raise AttributeError(name)
            if name in self._data:
                value = self._data[name]
                return str(value)
            else:
                return ""

        def __getitem__(self, key):
            if key in self._data:
                return str(self._data[key])
            else:
                return ""

    # Create the report wrapper
    report_wrapper = ReportWrapper(report)

    # Render the template
    tmpl = env.from_string(template)
    result = tmpl.render(report=report_wrapper)

    return result
