def render_report_header(template: str, report: dict) -> str:
    """
    Render a report header by substituting placeholders in the template
    with values from the report dictionary.

    Placeholders are in the form {key} where key is a key in the report dict.
    If a key is not found in the report, the placeholder is left as-is.
    """
    def replace(match):
        key = match.group(1)
        if key in report:
            return str(report[key])
        return match.group(0)

    import re
    return re.sub(r'\{(\w+)\}', replace, template)
