    env2.filters['upper'] = str.upper
    env2.filters['lower'] = str.lower
    env2.filters['capitalize'] = str.capitalize

    # Remove other filters that might be present
    # Actually, let's just create a fresh environment with only our filters
    # The default filters are still there, but we only care about the ones we use

