    """Manual fallback renderer for simple cases."""
    # Pattern to match {{ variable }} or {{ variable|filter }}
    # Spaces are optional inside braces and around pipe
    pattern = re.compile(r'\{\{\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*(?:\|\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*)?\}\}')

    def replace_match(match):
