            elif filter_name == 'lower':
                value = str(value).lower()
            elif filter_name == 'capitalize':
                value = str(value).capitalize()
            else:
                # Unknown filter, return empty
                value = ''

        return str(value)

    return pattern.sub(replace_match, template)
