import re
from jinja2 import Environment, BaseLoader, StrictUndefined, SandboxedEnvironment


def render_greeting_card(template: str, recipient: str, sender: str) -> str:
    """
    Render a greeting card template using Jinja2 with security measures.

    Args:
        template: Jinja2 template string
        recipient: Name of the recipient
        sender: Name of the sender

    Returns:
        Rendered string
    """
    # Create a sandboxed environment for security
    env = SandboxedEnvironment(
        loader=BaseLoader(),
        undefined=StrictUndefined,
        autoescape=False,
        trim_blocks=False,
        lstrip_blocks=False,
    )

    # Define supported filters
    env.filters['upper'] = lambda s: str(s).upper()
    env.filters['lower'] = lambda s: str(s).lower()
    env.filters['capitalize'] = lambda s: str(s).capitalize()

    # Create a custom undefined class that returns empty string for unknown variables
    class EmptyUndefined:
        def __str__(self):
            return ""
        def __repr__(self):
            return ""
        def __bool__(self):
            return False
        def __iter__(self):
            return iter([])
        def __getattr__(self, name):
            return EmptyUndefined()
        def __getitem__(self, key):
            return EmptyUndefined()
        def __call__(self, *args, **kwargs):
            return EmptyUndefined()

    # Override undefined to use our custom class
    env.undefined = EmptyUndefined

    # Parse and render the template
    try:
        tmpl = env.from_string(template)
        result = tmpl.render(recipient=recipient, sender=sender)
        return str(result)
    except Exception:
        # If there's any error, return empty string or handle gracefully
        return ""
