def render_greeting_card(template: str, recipient: str, sender: str) -> str:
    """
    Renderiza una tarjeta de felicitación usando Jinja2 con variables limitadas.

    Args:
        template: Plantilla Jinja2 con variables {{ recipient }} y {{ sender }}
        recipient: Nombre del destinatario
        sender: Nombre del remitente

    Returns:
        El texto renderizado de la tarjeta
    """
    from jinja2 import Environment, BaseLoader, StrictUndefined

    # Crear un entorno Jinja2 seguro con undefined estricto
    env = Environment(
        loader=BaseLoader(),
        undefined=StrictUndefined,
        autoescape=False,  # No escapar valores, insertar tal cual
        trim_blocks=True,
        lstrip_blocks=True
    )

    # Definir los filtros personalizados
    def upper_filter(value):
        return str(value).upper()

    def lower_filter(value):
        return str(value).lower()

    def capitalize_filter(value):
        return str(value).capitalize()

    # Registrar los filtros
    env.filters['upper'] = upper_filter
    env.filters['lower'] = lower_filter
    env.filters['capitalize'] = capitalize_filter

    # Crear un contexto seguro con solo las variables permitidas
    # Usamos un dict proxy que devuelve cadena vacía para variables no permitidas
    class SafeContext(dict):
        def __missing__(self, key):
            return ""

    context = SafeContext({
        'recipient': recipient,
        'sender': sender
    })

    try:
        # Renderizar la plantilla
        rendered = env.from_string(template).render(context)
        return rendered
    except Exception:
        # Si hay algún error, devolver cadena vacía o manejar adecuadamente
        return ""
