def log_requests(log_path: str, requests: list[dict]) -> int:
    """
    Append one line per request to the text file at log_path.

    Each line has the format: <timestamp> <ip> "<path>" "<user_agent>"
    Returns the number of lines appended.
    """
    if not isinstance(log_path, str):
        raise TypeError("log_path must be a string")

    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    # Validate each request dict
    required_keys = {'timestamp', 'ip', 'path', 'user_agent'}
    for i, req in enumerate(requests):
        if not isinstance(req, dict):
            raise TypeError(f"Each request must be a dict, got {type(req)} at index {i}")
        missing = required_keys - set(req.keys())
        if missing:
            raise ValueError(f"Request at index {i} missing keys: {missing}")
        for key in required_keys:
            if not isinstance(req[key], str):
                raise TypeError(f"Request at index {i}, key '{key}' must be a string")

    # Build the lines
    lines = []
    for req in requests:
        line = f'{req["timestamp"]} {req["ip"]} "{req["path"]}" "{req["user_agent"]}"\n'
        lines.append(line)

    # Write to file in append mode, UTF-8 encoding
    with open(log_path, 'a', encoding='utf-8') as f:
        for line in lines:
            f.write(line)

    return len(lines)
