def log_requests(log_path: str, requests: list[dict]) -> int:
    """
    Añade una línea por petición al final del archivo de texto en la ruta log_path.

    Args:
        log_path: Ruta al archivo de log
        requests: Lista de diccionarios con las claves 'timestamp', 'ip', 'path', 'user_agent'

    Returns:
        Número de líneas añadidas
    """
    if not isinstance(log_path, str) or not log_path:
        raise ValueError("log_path debe ser una cadena no vacía")

    if not isinstance(requests, list):
        raise TypeError("requests debe ser una lista")

    # Validar que cada elemento es un diccionario con las claves requeridas
    required_keys = {'timestamp', 'ip', 'path', 'user_agent'}
    for i, req in enumerate(requests):
        if not isinstance(req, dict):
            raise TypeError(f"El elemento {i} de requests debe ser un diccionario")
        missing_keys = required_keys - set(req.keys())
        if missing_keys:
            raise ValueError(f"El elemento {i} de requests falta las claves: {missing_keys}")
        for key in required_keys:
            if not isinstance(req[key], str):
                raise TypeError(f"El valor de '{key}' en el elemento {i} debe ser una cadena")

    # Construir las líneas
    lines = []
    for req in requests:
        line = f"{req['timestamp']} {req['ip']} \"{req['path']}\" \"{req['user_agent']}\"\n"
        lines.append(line)

    # Escribir en el archivo en modo append, conservando el contenido existente
    try:
        with open(log_path, 'a', encoding='utf-8') as f:
            for line in lines:
                f.write(line)
    except OSError as e:
        raise OSError(f"Error al escribir en el archivo {log_path}: {e}") from e

    return len(lines)
