def check_status(url: str) -> int:
    """
    Send a HEAD request to the given URL with a 5-second timeout and return the HTTP status code.
    If a requests.RequestException (or subclass) is raised, return 0.
    """
    try:
        # Validate URL scheme to prevent SSRF and other security issues
        parsed = requests.utils.parse_url(url)
        if parsed.scheme not in ('http', 'https'):
            return 0

        # Check for IP addresses that are private/reserved to prevent SSRF
        from urllib.parse import urlparse
        hostname = parsed.hostname
        if hostname:
            import ipaddress
            try:
                ip = ipaddress.ip_address(hostname)
                if ip.is_private or ip.is_loopback or ip.is_reserved or ip.is_unspecified:
                    return 0
            except ValueError:
                # Not an IP address, it's a hostname - allow it
                pass

        response = requests.head(url, timeout=5, allow_redirects=True)
        return int(response.status_code)
    except requests.RequestException:
        return 0
    except Exception:
        return 0
